function renameAndMoveImages() {
  const parentFolder = DriveApp.getFolderById("1_bbWKLTXU9j3q2ZahM6tFsiokjtqXhn0");

  processFolder(parentFolder, parentFolder);
  removeDuplicatesByName(parentFolder);
}


// يمشي داخل كل المجلدات (حتى nested folders)
function processFolder(folder, root) {
  const subfolders = folder.getFolders();

  while (subfolders.hasNext()) {
    const sub = subfolders.next();

    // دخول عميق داخل أي مجلد
    processFolder(sub, root);

    const plantName = sub.getName();
    let counter = 1;

    const files = sub.getFiles();
    while (files.hasNext()) {
      const file = files.next();

      const originalName = file.getName();
      const extension = originalName.includes(".")
        ? originalName.substring(originalName.lastIndexOf("."))
        : "";

      const newName = plantName + counter + extension;
      file.setName(newName);

      // نقل للـ web الرئيسي
      root.addFile(file);
      sub.removeFile(file);

      counter++;
    }
  }
}


// حذف التكرارات داخل web (يبقي آخر نسخة فقط)
function removeDuplicatesByName(folder) {
  const files = folder.getFiles();
  const seen = {};

  while (files.hasNext()) {
    const file = files.next();
    const name = file.getName();

    if (seen[name]) {
      // حذف النسخة القديمة
      seen[name].setTrashed(true);
    }

    // الاحتفاظ بالنسخة الأخيرة
    seen[name] = file;
  }
}
